// TH15 v1.00b st02bs.ecl / Boss3 (stage 2 boss nonspell 3), source lines 347-412.
// Helpers: Boss3_at 414-465, Boss3_at2 467-505. Source frames are noted as t=<line>.
// Card frame mapping: entry (timerReset, line 363) is t=0; the 120-frame shell buffer
// puts t=0 at harness frame ~123 (main->control->pattern->source_enemy spawn chain).
const TIME_LIMIT: int = 2224;   // 120 buffer + 2100 source window + 4 startup margin
const OPENING_BUFFER: int = 120;

// TH15 synthetic bullet vocabulary (native type 5 and 18 slots).
const TH15_BALL2: int = 432;
const TH15_BIG_BALL: int = 640;

// --- Boss3_at movement state -------------------------------------------------
// self_int(0) = next movement step count, self_fx(0)/self_fx(1) = logical unit dir.
// moveLimit(0,128,280,96): clamp x[-140,140], y[80,176]; direction interior x+-70, y104..152.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

// 412 moveRand(60,4,1.0): mode 4 does not touch the speed slot (linear 1-k/60).
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard (0.05 rad); unreachable for these direction ranges.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// 414-465 Boss3_at: ring of growing size; per-ring base angle steps by C.
// etSprite(0,5,2), etAim(0,3) fixed ring, etOffset(0,0,-8), etDist starts 90 and drops 3,
// speed starts 1.5 and rises 0.05, ways start 1. ANIM birth exit keeps position -= 4*velocity.
async sub boss3_at(base: angle, delta: angle, n: int, gap: int) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_offset(0, 0fx, -8fx);
    var dist: fx = 90fx;
    var ways: int = 1;
    var speed: fx = 1.5fx;
    var a: int = base as int;
    var step: int = delta as int;
    for k in 0..n {
        var d: fx = dist - 4fx * speed;
        sh_count(0, ways, 1);
        sh_speed(0, speed, 0fx);
        sh_angle(0, a as angle, 0deg);
        sh_dist(0, d);
        sh_fire(0);
        dist = dist - 3fx;
        a = a + step;
        ways = ways + 1;
        speed = speed + 0.05fx;
        wait(gap);
    }
}

// 467-505 Boss3_at2 (HL only): aimed big-ball stream, 600 shots.
// etSprite(1,18,3), etAim(1,3) + ANGLE_PLAYER each shot; speed 3.0 L / 2.0 H.
async sub boss3_at2(speed: fx, gap: int) {
    wait(100);
    sh_reset(0);
    sh_sprite(0, TH15_BIG_BALL, 3);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_count(0, 1, 1);
    sh_speed(0, speed, 0fx);
    sh_angle(0, 0deg, 0deg);
    for c in 0..600 {
        sh_angle(0, 0deg, 0deg);
        sh_fire(0);
        wait(gap);
    }
}

// 347-412 Boss3 entry.
async sub source_enemy() {
    set_invuln(65535);   // shell invulnerability replaces source setInvuln(120), line 349
    set_hitbox(24fx);    // 501 setHitbox(48,48) -> r=24
    set_hurtbox(20fx);   // 500 setHurtbox(40,40) -> r=20
    // 363-371: stop movement and clear bullets around the boss at segment entry.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    // 387 movePosTime(90,9,0,96): (0,128) -> (0,96), source mode 9.
    move_to(90, 0fx, 96fx, EASE_QUAD_IN_OUT);
    wait(60);
    wait(60);
    // 396-398: Boss3_at2 runs only on Hard/Lunatic.
    if global(GVAR_RANK) >= RANK_HARD {
        var at2_speed: fx = 2fx;
        var at2_gap: int = 60;
        if global(GVAR_RANK) >= RANK_LUNATIC {
            at2_speed = 3fx;
            at2_gap = 30;
        }
        spawn boss3_at2(at2_speed, at2_gap);
    }
    loop {
        // 440 diffI($I,20,32,34,36); per-shot wait E=8, N/H/L=6.
        var n: int = 34;
        var gap: int = 6;
        var rank: int = global(GVAR_RANK);
        if rank == RANK_EASY {
            n = 20;
            gap = 8;
        } else if rank == RANK_NORMAL {
            n = 32;
        } else if rank == RANK_LUNATIC {
            n = 36;
        }
        // 400-408: Boss3_at alternating C=-4deg / +4deg around the 160+60 frame cycle.
        spawn boss3_at(90deg, -4deg, n, gap);
        wait(160);
        card_move_rand();
        card_wait(60);
        spawn boss3_at(90deg, 4deg, n, gap);
        wait(160);
        card_move_rand();
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13500, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
